import type { HTMLAttributes } from "react";

const join = (base: string, extra = "") => `${base} ${extra}`.trim();
export function Item({ className, ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={join("co-flex co-items-center co-gap-3 co-rounded-lg co-p-3 hover:co-bg-black/5", className)} {...props} />; }
export function ItemMedia({ className, ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={join("co-grid co-size-10 co-shrink-0 co-place-items-center co-rounded-md co-bg-black/5", className)} {...props} />; }
export function ItemContent({ className, ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={join("co-min-w-0 co-flex-1", className)} {...props} />; }
export function ItemTitle({ className, ...props }: HTMLAttributes<HTMLHeadingElement>) { return <h3 className={join("co-font-medium", className)} {...props} />; }
export function ItemDescription({ className, ...props }: HTMLAttributes<HTMLParagraphElement>) { return <p className={join("co-text-sm co-text-black/55", className)} {...props} />; }
export function ItemActions({ className, ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={join("co-ms-auto co-flex co-items-center co-gap-2", className)} {...props} />; }
